def tree_manifest(root: Path) -> dict[str, Any]:
    if not root.is_dir():
        raise FanoutError("TREE_NOT_FOUND", str(root))
    files = []
    for path in sorted((item for item in root.rglob("*") if item.is_file()), key=lambda item: item.relative_to(root).as_posix()):
        relative = path.relative_to(root).as_posix()
        files.append({"path": relative, "sha256": sha256_file(path), "bytes": path.stat().st_size})
    digest = sha256_bytes(canonical_json_bytes(files))
    return {"sha256": digest, "file_count": len(files), "total_bytes": sum(item["bytes"] for item in files), "files": files}

def _validate_corpus(value: dict[str, Any], source_root: Path) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    exact_keys(value, {"schema_version", "scope", "documents"}, "corpus")
    if value["schema_version"] != 1 or value["scope"] != "isolated-page-fanout-benchmark":
        raise FanoutError("INVALID_CORPUS", "schema_version/scope 非法")
    if not isinstance(value["documents"], list) or len(value["documents"]) < 3:
        raise FanoutError("INVALID_CORPUS", "至少需要三类单文档输入")
    documents: list[dict[str, Any]] = []
    candidates: list[dict[str, Any]] = []
    seen_documents: set[str] = set()
    seen_candidates: set[str] = set()
    seen_categories: set[str] = set()
    for document in value["documents"]:
        exact_keys(
            document,
            {"document_id", "category", "path", "conservative_page", "origin", "license", "source_sha256", "candidates"},
            "document",
        )
        document_id = validate_identifier(document["document_id"], "document_id")
        category = validate_identifier(document["category"], "category")
        if document_id in seen_documents:
            raise FanoutError("DUPLICATE_DOCUMENT", document_id)
        if category in seen_categories:
            raise FanoutError("DUPLICATE_CATEGORY", category)
        seen_documents.add(document_id)
        seen_categories.add(category)
        validate_relative_path(document["conservative_page"], "document.conservative_page")
        if not isinstance(document["origin"], str) or not document["origin"].startswith("fixture://"):
            raise FanoutError("UNTRUSTED_FIXTURE_ORIGIN", document_id)
        if document["license"] != "CC0-1.0":
            raise FanoutError("UNREVIEWED_FIXTURE_LICENSE", document_id)
        if not isinstance(document["source_sha256"], str) or not re.fullmatch(r"[0-9a-f]{64}", document["source_sha256"]):
            raise FanoutError("INVALID_SOURCE_HASH", document_id)
        _path, lines = _source_lines(source_root, document)
        if not isinstance(document["candidates"], list) or not document["candidates"]:
            raise FanoutError("EMPTY_CANDIDATES", document_id)
        for candidate in document["candidates"]:
            normalized = _validate_candidate(candidate, document, lines)
            if normalized["candidate_id"] in seen_candidates:
                raise FanoutError("DUPLICATE_CANDIDATE_ID", normalized["candidate_id"])
            seen_candidates.add(normalized["candidate_id"])
            candidates.append(normalized)
        documents.append(document)
    return documents, sorted(candidates, key=lambda item: (item["document_id"], item["candidate_id"]))

def _resolve_link(page: str, target: str) -> str:
    target_path = PurePosixPath(target)
    if target_path.suffix != ".md":
        target_path = target_path.with_suffix(".md")
    if target.startswith("/"):
        candidate = target_path.relative_to("/")
    else:
        candidate = PurePosixPath(page).parent / target_path
    stack: list[str] = []
    for part in candidate.parts:
        if part in {"", "."}:
            continue
        if part == "..":
            if not stack:
                raise FanoutError("LINK_OUTSIDE_OUTPUT", f"{page} -> {target}")
            stack.pop()
        else:
            stack.append(part)
    return PurePosixPath(*stack).as_posix()

def _resolve(page: str, target: str) -> str | None:
    if ":" in target or target.startswith("#"):
        return None
    value = PurePosixPath(target)
    if value.suffix != ".md":
        value = value.with_suffix(".md")
    candidate = value.relative_to("/") if target.startswith("/") else PurePosixPath(page).parent / value
    stack: list[str] = []
    for part in candidate.parts:
        if part in {"", "."}:
            continue
        if part == "..":
            if not stack:
                return None
            stack.pop()
        else:
            stack.append(part)
    return PurePosixPath(*stack).as_posix()

def _page_graph(root: Path, projection: dict[str, Any]) -> tuple[dict[str, list[str]], list[dict[str, str]], list[dict[str, Any]]]:
    declared: set[str] = set()
    page_files: list[dict[str, Any]] = []
    for item in projection["pages"]:
        exact_keys(item, {"path", "title", "kind"}, "projection.pages[]")
        relative = validate_relative_path(item["path"], "projection.pages[].path")
        if not relative.endswith(".md") or relative in declared:
            raise FanoutError("INVALID_PROJECTION", f"重复或非 Markdown 页面：{relative}")
        path = root / relative
        if not path.is_file():
            raise FanoutError("PROJECTED_PAGE_NOT_FOUND", relative)
        text = path.read_text(encoding="utf-8")
        title = TITLE.search(text)
        if not title or title.group(1).strip() != item["title"]:
            raise FanoutError("PROJECTED_TITLE_MISMATCH", relative)
        declared.add(relative)
        page_files.append(
            {
                "path": relative,
                "title": item["title"],
                "kind": item["kind"],
                "bytes": path.stat().st_size,
                "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
            }
        )
    actual = {path.relative_to(root).as_posix() for path in root.rglob("*.md")}
    if actual != declared:
        raise FanoutError("PROJECTION_PAGE_SET_DRIFT", f"missing={sorted(declared-actual)} extra={sorted(actual-declared)}")
    graph: dict[str, list[str]] = {}
    broken: list[dict[str, str]] = []
    for page in sorted(declared):
        targets: list[str] = []
        text = (root / page).read_text(encoding="utf-8")
        for raw in WIKI_LINK.findall(text):
            resolved = _resolve(page, raw.strip())
            if resolved is None or resolved not in declared:
                broken.append({"page": page, "target": raw.strip(), "resolved": resolved or "outside"})
            else:
                targets.append(resolved)
        graph[page] = sorted(set(targets))
    return graph, broken, sorted(page_files, key=lambda item: item["path"])

def _shortest_path(graph: dict[str, list[str]], start: str, target: str) -> list[str] | None:
    queue: deque[list[str]] = deque([[start]])
    seen = {start}
    while queue:
        path = queue.popleft()
        if path[-1] == target:
            return path
        for neighbor in graph.get(path[-1], []):
            if neighbor not in seen:
                seen.add(neighbor)
                queue.append([*path, neighbor])
    return None

def _reachable(graph: dict[str, list[str]], start: str) -> set[str]:
    queue = deque([start])
    seen = {start}
    while queue:
        for neighbor in graph.get(queue.popleft(), []):
            if neighbor not in seen:
                seen.add(neighbor)
                queue.append(neighbor)
    return seen

def _duplicate_titles(page_files: list[dict[str, Any]], threshold: float) -> list[dict[str, Any]]:
    result: list[dict[str, Any]] = []
    for index, left in enumerate(page_files):
        left_topic = normalize_topic(left["title"])
        for right in page_files[index + 1 :]:
            right_topic = normalize_topic(right["title"])
            score = SequenceMatcher(None, left_topic, right_topic, autojunk=False).ratio()
            if score >= threshold:
                result.append(
                    {
                        "left": left["path"],
                        "right": right["path"],
                        "similarity": round(score, 6),
                        "threshold": threshold,
                    }
                )
    return result

def validate_model_artifacts(model_dir: Path, manifest_path: Path) -> dict[str, Any]:
    manifest = json_load(manifest_path)
    if manifest.get("status") != "verified-local-snapshot":
        raise ModelUnavailable("model artifact manifest is not verified-local-snapshot")
    if not model_dir.is_dir():
        raise ModelUnavailable(f"model snapshot directory is missing: {model_dir}")
    expected = {item["path"]: item for item in manifest.get("files", [])}
    if not expected:
        raise ModelUnavailable("model artifact manifest has no files")
    actual_paths = {
        item.relative_to(model_dir).as_posix()
        for item in model_dir.rglob("*")
        if item.is_file() and ".cache" not in item.relative_to(model_dir).parts
    }
    missing = sorted(set(expected) - actual_paths)
    extra = sorted(actual_paths - set(expected))
    mismatches = []
    for relative, item in sorted(expected.items()):
        path = model_dir / relative
        if path.is_file() and (
            path.stat().st_size != int(item["bytes"]) or sha256(path) != item["sha256"]
        ):
            mismatches.append(relative)
    if missing or extra or mismatches:
        raise ModelUnavailable(
            f"model snapshot identity drift: missing={missing}, extra={extra}, mismatches={mismatches}"
        )
    total = sum((model_dir / relative).stat().st_size for relative in expected)
    if total != int(manifest["total_bytes"]):
        raise ModelUnavailable("model snapshot total bytes differ from manifest")
    return {
        "repository": manifest["repository"],
        "revision": manifest["revision"],
        "files": len(expected),
        "total_bytes": total,
        "manifest_sha256": sha256(manifest_path),
    }

def render_documents(machine_path: Path, protocol: dict[str, Any]) -> list[dict[str, str]]:
    contract = protocol["document_contract"]
    fields = list(contract["fields_in_order"])
    select = ["entity_id", *fields]
    sql = f"SELECT {', '.join(select)} FROM entities WHERE source_path <> '' ORDER BY entity_id"
    if sql != contract["selection_sql"]:
        raise ValueError("document selection SQL differs from the frozen contract")
    with _readonly_connection(machine_path) as connection:
        connection.row_factory = sqlite3.Row
        rows = connection.execute(sql).fetchall()
    documents = []
    for row in rows:
        lines = []
        for field in fields:
            value = str(row[field] or "").strip()
            if value:
                lines.append(f"{field}: {value}")
        documents.append(
            {
                "entity_id": str(row["entity_id"]),
                "source_path": str(row["source_path"]).replace("\\", "/"),
                "qualified_name": str(row["qualified_name"]),
                "text": "\n".join(lines),
            }
        )
    if len(documents) != int(protocol["corpus"]["entity_rows_with_source_path"]):
        raise ValueError("rendered document count differs from the frozen protocol")
    return documents

